def __init__(self, detail=None, headers=None, comment=None,
             body_template=None, **kw):
    # Handle case where code or title might be None (base class instantiation)
    if self.code is None or self.title is None:
        status = '520 Unknown Error'
    else:
        status = '%s %s' % (self.code, self.title)
    Response.__init__(self, status=status, **kw)
    Exception.__init__(self, detail)
    self.detail = self.message = detail
    if headers:
        self.headers.extend(headers)
    self.comment = comment
    if body_template is not None:
        self.body_template = body_template
        self.body_template_obj = Template(body_template)

    if self.empty_body:
        del self.content_type
        del self.content_length
